('g6_1_soc_u2_L01_basic#1','soc',6,1,'u2','L01','g6_1_soc_u2_L01_basic','lesson_basic','SO6-1-u2-C1',1,'mc','auto','국민이 자신들을 대표할 사람을 투표로 뽑는 일을 무엇이라고 하나요?',ARRAY['SO6-1-u2-X02','SO6-1-u2-X01']::text[],false,'{"seq":1,"concept":"SO6-1-u2-C1","difficulty":1,"kind":"mc","stem":"국민이 자신들을 대표할 사람을 투표로 뽑는 일을 무엇이라고 하나요?","options":[{"t":"선거","correct":true},{"t":"추첨","mis":"SO6-1-u2-X02"},{"t":"임명","mis":"SO6-1-u2-X02"},{"t":"회식","mis":"SO6-1-u2-X01"}],"explanation":["투표로 뽑아요.","대표를 뽑는 일이에요.","선거예요."]}'::jsonb),
('g6_1_soc_u2_L01_basic#2','soc',6,1,'u2','L01','g6_1_soc_u2_L01_basic','lesson_basic','SO6-1-u2-C1',1,'sa','auto','선거에서 대표를 뽑을 수 있는 권리를 가진 사람을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-1-u2-C1","difficulty":1,"kind":"sa","stem":"선거에서 대표를 뽑을 수 있는 권리를 가진 사람을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["유권자"],"explanation":["권리를 가진 사람이에요.","유◯자예요.","유권자예요."],"mis":"SO6-1-u2-X02"}'::jsonb),
('g6_1_soc_u2_L01_basic#3','soc',6,1,'u2','L01','g6_1_soc_u2_L01_basic','lesson_basic','SO6-1-u2-C1',1,'ox','auto','우리나라에서는 모든 국민이 정치에 직접 참여하여 나라의 일을 모두 결정해요.',ARRAY['SO6-1-u2-X01']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C1","difficulty":1,"kind":"ox","stem":"우리나라에서는 모든 국민이 정치에 직접 참여하여 나라의 일을 모두 결정해요.","answer":"X","reason_options":[{"t":"모든 국민이 직접 나랏일을 결정하기 어려워 대표를 뽑아 맡기기 때문에","correct":true},{"t":"나랏일은 국민 모두가 날마다 모여 정하기 때문에","mis":"SO6-1-u2-X01"}],"mis":"SO6-1-u2-X01","explanation":["모두 직접 하기는 어려워요.","대표를 뽑아 맡겨요.","그래서 X예요."]}'::jsonb),
('g6_1_soc_u2_L01_basic#4','soc',6,1,'u2','L01','g6_1_soc_u2_L01_basic','lesson_basic','SO6-1-u2-C1',1,'mc','auto','선거로 뽑는 우리나라의 대표로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X02']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C1","difficulty":1,"kind":"mc","stem":"선거로 뽑는 우리나라의 대표로 알맞은 것은 어느 것인가요?","options":[{"t":"교육감","correct":true},{"t":"은행원","mis":"SO6-1-u2-X02"},{"t":"기자","mis":"SO6-1-u2-X02"},{"t":"운동선수","mis":"SO6-1-u2-X02"}],"explanation":["선거로 뽑는 자리예요.","지역의 교육을 맡는 대표예요.","교육감이에요."]}'::jsonb),
('g6_1_soc_u2_L01_basic#5','soc',6,1,'u2','L01','g6_1_soc_u2_L01_basic','lesson_basic','SO6-1-u2-C1',2,'mc','auto','메모의 ㉠~㉢을 이어 읽을 때 대표를 뽑는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X01','SO6-1-u2-X02']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C1","difficulty":2,"kind":"mc","stem":"메모의 ㉠~㉢을 이어 읽을 때 대표를 뽑는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"결정할 일은 많은데 모든 국민이 직접 정하기 어렵기 때문에","correct":true},{"t":"나랏일이 적어 몇 사람만 있으면 되기 때문에","mis":"SO6-1-u2-X01"},{"t":"국민은 나랏일에 관심을 두면 안 되기 때문에","mis":"SO6-1-u2-X01"},{"t":"대표가 국민보다 언제나 더 많이 알기 때문에","mis":"SO6-1-u2-X02"}],"explanation":["㉠은 일이 많다는 거예요.","㉡은 모두 직접은 어렵다는 거예요.","그래서 대표를 뽑아요."],"asset":{"type":"passage","lines":["㉠ 나라를 운영하려면 결정해야 할 중요한 일이 아주 많다.","㉡ 모든 국민이 한자리에 모여 나랏일을 모두 직접 정하기는 어렵다.","㉢ 그래서 국민은 자신을 대신할 대표를 뽑아 나랏일을 맡긴다."],"title":"대표를 뽑는 까닭 메모"}}'::jsonb),
('g6_1_soc_u2_L01_basic#6','soc',6,1,'u2','L01','g6_1_soc_u2_L01_basic','lesson_basic','SO6-1-u2-C1',2,'blank','auto','민주주의란 국민이 국가의 (    )으로서 권리를 갖고, 그 권리를 자유롭고 평등하게 행사하는 정치 형태예요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u2-X03']::text[],false,'{"seq":6,"concept":"SO6-1-u2-C1","difficulty":2,"kind":"blank","stem":"민주주의란 국민이 국가의 (    )으로서 권리를 갖고, 그 권리를 자유롭고 평등하게 행사하는 정치 형태예요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"주인","correct":true},{"t":"손님","mis":"SO6-1-u2-X03"},{"t":"구경꾼","mis":"SO6-1-u2-X03"},{"t":"심부름꾼","mis":"SO6-1-u2-X03"}],"explanation":["나라의 주인은 누구일까요?","국민이 권리를 가져요.","주인이에요."]}'::jsonb),
('g6_1_soc_u2_L01_basic#7','soc',6,1,'u2','L01','g6_1_soc_u2_L01_basic','lesson_basic','SO6-1-u2-C1',2,'mc','auto','세 친구가 말한 경험의 공통점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X02']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C1","difficulty":2,"kind":"mc","stem":"세 친구가 말한 경험의 공통점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"모두 대표를 뽑는 일과 관련 있다","correct":true},{"t":"모두 법을 만드는 일과 관련 있다","mis":"SO6-1-u2-X02"},{"t":"모두 물건을 사고파는 일과 관련 있다","mis":"SO6-1-u2-X02"},{"t":"모두 대표를 추첨으로 정한 경험이다","mis":"SO6-1-u2-X02"}],"explanation":["학급 회장, 투표소, 연설이에요.","모두 대표를 뽑는 장면이에요.","선거와 관련 있어요."],"asset":{"type":"speech","turns":[{"who":"친구 가","text":"학급 회장 선거에서 투표해 본 적이 있어."},{"who":"친구 나","text":"부모님을 따라 투표소에 가 본 적이 있어."},{"who":"친구 다","text":"거리에서 후보자가 연설하는 모습을 본 적이 있어."}]}}'::jsonb),
('g6_1_soc_u2_L01_basic#8','soc',6,1,'u2','L01','g6_1_soc_u2_L01_basic','lesson_basic','SO6-1-u2-C1',2,'match','auto','낱말과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-1-u2-C1","difficulty":2,"kind":"match","stem":"낱말과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"선거","r":"국민이 대표할 사람을 투표로 뽑는 일"},{"l":"유권자","r":"대표를 뽑을 수 있는 권리를 가진 사람"},{"l":"민주주의","r":"국민이 주인으로서 권리를 갖고 행사하는 정치 형태"},{"l":"대표","r":"국민을 대신해 나랏일을 맡는 사람"}],"mis":"SO6-1-u2-X02","explanation":["뽑는 일 · 뽑는 사람이에요.","주인으로서 권리를 행사해요.","대표는 맡는 사람이에요."]}'::jsonb),
('g6_1_soc_u2_L01_basic#9','soc',6,1,'u2','L01','g6_1_soc_u2_L01_basic','lesson_basic','SO6-1-u2-C1',2,'mc','auto','마을 게시판에 이런 행사 안내를 붙인 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X03','SO6-1-u2-X01']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C1","difficulty":2,"kind":"mc","stem":"마을 게시판에 이런 행사 안내를 붙인 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사람들이 선거에 참여하도록 북돋우려고","correct":true},{"t":"사진을 많이 모으려고","mis":"SO6-1-u2-X03"},{"t":"음료를 팔려고","mis":"SO6-1-u2-X03"},{"t":"투표하러 가지 않게 하려고","mis":"SO6-1-u2-X01"}],"explanation":["투표를 마치고 찍은 사진이에요.","투표는 국민의 권리예요.","참여를 북돋우려는 거예요."],"asset":{"type":"passage","lines":["「투표를 마치고 투표소 밖에서 찍은 사진을 올려 주세요.」","「참여해 주신 분 가운데 몇 분께 음료를 드립니다.」","「투표는 국민의 권리입니다.」"],"title":"어느 마을 게시판에 붙은 행사 안내"}}'::jsonb),
('g6_1_soc_u2_L01_basic#10','soc',6,1,'u2','L01','g6_1_soc_u2_L01_basic','lesson_basic','SO6-1-u2-C1',3,'error','auto','선거를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X02','SO6-1-u2-X01']::text[],false,'{"seq":10,"concept":"SO6-1-u2-C1","difficulty":3,"kind":"error","stem":"선거를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「대표는 나라에서 아무나 골라 정해 주는 거야.」","correct":true,"mis_target":"SO6-1-u2-X02"},{"t":"친구 가 — 「국민이 투표로 대표를 뽑는 일이 선거야.」","mis":"SO6-1-u2-X02"},{"t":"친구 나 — 「뽑은 대표에게 나랏일을 맡기는 거야.」","mis":"SO6-1-u2-X01"}],"explanation":["대표는 누가 뽑을까요?","국민이 투표로 뽑아요.","친구 다가 잘못 말했어요."]}'::jsonb),
('g6_1_soc_u2_L01_challenge#1','soc',6,1,'u2','L01','g6_1_soc_u2_L01_challenge','lesson_challenge','SO6-1-u2-C1',2,'sa','auto','선거는 국민이 주인으로서 권리를 행사하는 가장 기본적인 방법이라 「민주주의의 ○」이라고 불려요. ○에 알맞은 한 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u2-C1","difficulty":2,"kind":"sa","stem":"선거는 국민이 주인으로서 권리를 행사하는 가장 기본적인 방법이라 「민주주의의 ○」이라고 불려요. ○에 알맞은 한 글자를 쓰세요.","answer":["꽃"],"explanation":["가장 빛나는 부분이에요.","봄에 피어요.","꽃이에요."],"mis":"SO6-1-u2-X03"}'::jsonb),
('g6_1_soc_u2_L01_challenge#2','soc',6,1,'u2','L01','g6_1_soc_u2_L01_challenge','lesson_challenge','SO6-1-u2-C1',2,'ox','auto','오늘날 대부분의 민주주의 국가는 자신들을 대신할 대표를 뽑아 나라의 중요한 일을 맡기고 있어요.',ARRAY['SO6-1-u2-X01']::text[],false,'{"seq":2,"concept":"SO6-1-u2-C1","difficulty":2,"kind":"ox","stem":"오늘날 대부분의 민주주의 국가는 자신들을 대신할 대표를 뽑아 나라의 중요한 일을 맡기고 있어요.","answer":"O","reason_options":[{"t":"모든 국민이 직접 나랏일을 결정하고 살림을 운영하기 어렵기 때문에","correct":true},{"t":"민주주의 국가에서는 국민이 나랏일에 참여할 수 없기 때문에","mis":"SO6-1-u2-X01"}],"mis":"SO6-1-u2-X01","explanation":["대표에게 맡겨요.","모두 직접은 어려워요.","그래서 O예요."]}'::jsonb),
('g6_1_soc_u2_L01_challenge#3','soc',6,1,'u2','L01','g6_1_soc_u2_L01_challenge','lesson_challenge','SO6-1-u2-C1',3,'mc','auto','반 친구 모두가 한꺼번에 전교 회의에 갈 수 없어 학급 대표를 뽑아 보내는 것과 가장 비슷한 까닭은 메모의 어느 것인가요?',ARRAY['SO6-1-u2-X01']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C1","difficulty":3,"kind":"mc","stem":"반 친구 모두가 한꺼번에 전교 회의에 갈 수 없어 학급 대표를 뽑아 보내는 것과 가장 비슷한 까닭은 메모의 어느 것인가요?","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"SO6-1-u2-X01"},{"t":"㉢","mis":"SO6-1-u2-X01"},{"t":"㉠과 ㉢","mis":"SO6-1-u2-X01"}],"explanation":["모두 갈 수 없어요.","모두 직접 정하기 어려운 것과 같아요.","㉡이에요."],"asset":{"type":"passage","lines":["㉠ 나라를 운영하려면 결정해야 할 중요한 일이 아주 많다.","㉡ 모든 국민이 한자리에 모여 나랏일을 모두 직접 정하기는 어렵다.","㉢ 그래서 국민은 자신을 대신할 대표를 뽑아 나랏일을 맡긴다."],"title":"대표를 뽑는 까닭 메모"}}'::jsonb),
('g6_1_soc_u2_L01_challenge#4','soc',6,1,'u2','L01','g6_1_soc_u2_L01_challenge','lesson_challenge','SO6-1-u2-C1',3,'mc','auto','민주주의에서 선거가 갖는 뜻을 바르게 설명한 것은 어느 것인가요?',ARRAY['SO6-1-u2-X03','SO6-1-u2-X02']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C1","difficulty":3,"kind":"mc","stem":"민주주의에서 선거가 갖는 뜻을 바르게 설명한 것은 어느 것인가요?","options":[{"t":"유권자의 뜻이 선거 결과에 반영되어 나랏일을 정하는 데 영향을 미친다","correct":true},{"t":"선거 결과는 유권자의 뜻과 관계없이 정해진다","mis":"SO6-1-u2-X03"},{"t":"선거가 끝나면 국민은 나랏일과 상관이 없어진다","mis":"SO6-1-u2-X03"},{"t":"선거는 대표끼리 서로를 뽑는 일이다","mis":"SO6-1-u2-X02"}],"explanation":["유권자의 뜻이 담겨요.","결과에 반영돼요.","나랏일에 영향을 미쳐요."]}'::jsonb),
('g6_1_soc_u2_L01_challenge#5','soc',6,1,'u2','L01','g6_1_soc_u2_L01_challenge','lesson_challenge','SO6-1-u2-C1',3,'mc','auto','「민주주의의 꽃」이라는 말에 담긴 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X03']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C1","difficulty":3,"kind":"mc","stem":"「민주주의의 꽃」이라는 말에 담긴 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"국민이 주인으로서 권리를 행사하는 가장 기본적인 방법이 선거라는 뜻","correct":true},{"t":"선거 날에는 꽃을 나누어 준다는 뜻","mis":"SO6-1-u2-X03"},{"t":"선거는 보기에만 좋고 쓸모는 없다는 뜻","mis":"SO6-1-u2-X03"},{"t":"선거가 끝나면 국민의 권리도 끝난다는 뜻","mis":"SO6-1-u2-X03"}],"explanation":["꽃은 가장 빛나는 부분이에요.","권리를 행사하는 방법이에요.","가장 기본적인 방법이라는 뜻이에요."]}'::jsonb),
('g6_1_soc_u2_L01_challenge#6','soc',6,1,'u2','L01','g6_1_soc_u2_L01_challenge','lesson_challenge','SO6-1-u2-C1',3,'ox','auto','학급 회장 선거도 구성원이 대표를 투표로 뽑는다는 점에서 나라의 선거와 같은 뜻을 지녀요.',ARRAY['SO6-1-u2-X02']::text[],false,'{"seq":6,"concept":"SO6-1-u2-C1","difficulty":3,"kind":"ox","stem":"학급 회장 선거도 구성원이 대표를 투표로 뽑는다는 점에서 나라의 선거와 같은 뜻을 지녀요.","answer":"O","reason_options":[{"t":"구성원이 자신을 대신할 사람을 투표로 뽑아 일을 맡기기 때문에","correct":true},{"t":"학급 회장은 선생님이 정해 주기 때문에","mis":"SO6-1-u2-X02"}],"mis":"SO6-1-u2-X02","explanation":["구성원이 뽑아요.","대신할 사람에게 맡겨요.","같은 뜻이에요."]}'::jsonb),
('g6_1_soc_u2_L01_challenge#7','soc',6,1,'u2','L01','g6_1_soc_u2_L01_challenge','lesson_challenge','SO6-1-u2-C1',3,'error','auto','민주주의를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X03']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C1","difficulty":3,"kind":"error","stem":"민주주의를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「민주주의에서는 대표가 주인이고 국민은 따르기만 해.」","correct":true,"mis_target":"SO6-1-u2-X03"},{"t":"친구 가 — 「국민이 나라의 주인으로서 권리를 가져.」","mis":"SO6-1-u2-X03"},{"t":"친구 다 — 「그 권리를 자유롭고 평등하게 행사해.」","mis":"SO6-1-u2-X03"}],"explanation":["주인은 누구일까요?","국민이 주인이에요.","친구 나가 잘못 말했어요."]}'::jsonb),
('g6_1_soc_u2_L01_challenge#8','soc',6,1,'u2','L01','g6_1_soc_u2_L01_challenge','lesson_challenge','SO6-1-u2-C1',4,'mc','auto','선거로 뽑는 대표 카드를 보고 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X02','SO6-1-u2-X01']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C1","difficulty":4,"kind":"mc","stem":"선거로 뽑는 대표 카드를 보고 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나라 전체의 대표뿐 아니라 지역과 교육을 맡을 대표도 선거로 뽑는다","correct":true},{"t":"나라 전체의 대표 한 사람만 선거로 뽑는다","mis":"SO6-1-u2-X02"},{"t":"지역의 대표는 나라에서 정해 준다","mis":"SO6-1-u2-X02"},{"t":"선거로 뽑는 대표는 모두 같은 일을 한다","mis":"SO6-1-u2-X01"}],"explanation":["대통령이 있어요.","시장·군수도 있어요.","교육감도 있어요."],"asset":{"type":"passage","lines":["대통령 · 도지사 · 시장","군수 · 구청장 · 교육감"],"title":"선거로 뽑는 대표 카드"}}'::jsonb),
('g6_1_soc_u2_L01_challenge#9','soc',6,1,'u2','L01','g6_1_soc_u2_L01_challenge','lesson_challenge','SO6-1-u2-C1',4,'mc','auto','대표를 뽑아 일을 맡긴 뒤에도 국민이 나라의 주인이라고 할 수 있는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X03','SO6-1-u2-X01']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C1","difficulty":4,"kind":"mc","stem":"대표를 뽑아 일을 맡긴 뒤에도 국민이 나라의 주인이라고 할 수 있는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"국민이 스스로 뽑아 뜻을 맡긴 것이고, 다음 선거에서 다시 뜻을 나타낼 수 있기 때문에","correct":true},{"t":"대표를 뽑으면 국민의 권리는 사라지기 때문에","mis":"SO6-1-u2-X03"},{"t":"대표가 국민 대신 주인이 되기 때문에","mis":"SO6-1-u2-X03"},{"t":"국민은 아무 일도 하지 않아도 되기 때문에","mis":"SO6-1-u2-X01"}],"explanation":["누가 뽑았나요?","뜻을 맡긴 거예요.","다시 뜻을 나타낼 수 있어요."]}'::jsonb),
('g6_1_soc_u2_L01_challenge#10','soc',6,1,'u2','L01','g6_1_soc_u2_L01_challenge','lesson_challenge','SO6-1-u2-C1',4,'essay','teacher','모든 국민이 직접 나랏일을 정하지 않고 선거로 대표를 뽑아 맡기는 까닭을 쓰고, 그런데도 선거를 「민주주의의 꽃」이라 부르는 까닭을 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u2-C1","difficulty":4,"kind":"essay","stem":"모든 국민이 직접 나랏일을 정하지 않고 선거로 대표를 뽑아 맡기는 까닭을 쓰고, 그런데도 선거를 「민주주의의 꽃」이라 부르는 까닭을 이어 쓰세요.","answer_guide":{"answer":"예: 나라를 운영하려면 정할 일이 많은데 모든 국민이 직접 참여해 나랏일을 모두 정하기는 어렵기 때문에 대표를 뽑아 일을 맡긴다. 그래도 그 대표를 국민이 직접 투표로 뽑고 그 뜻이 결과에 반영되므로, 선거는 국민이 나라의 주인으로서 권리를 행사하는 가장 기본적인 방법이라 민주주의의 꽃이라고 부른다.","scoring_points":["대표를 뽑는 까닭을 썼는가","선거에서 국민이 권리를 행사함을 썼는가","민주주의의 꽃이라 부르는 까닭과 이었는가"]},"explanation":["모두 직접은 어려워요.","국민이 뽑아요.","주인의 권리를 행사해요."]}'::jsonb),
