('g6_1_soc_u2_L09_challenge#9','soc',6,1,'u2','L09','g6_1_soc_u2_L09_challenge','lesson_challenge','SO6-1-u2-C14',4,'mc','auto','국회·행정부·법원과 국민의 관계를 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO6-1-u2-X27','SO6-1-u2-X29','SO6-1-u2-X01']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C14","difficulty":4,"kind":"mc","stem":"국회·행정부·법원과 국민의 관계를 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"세 기관이 권력을 나눠 맡아 서로 견제하고, 국민은 그 권력이 올바르게 쓰이는지 지켜본다","correct":true},{"t":"세 기관 가운데 하나가 나머지를 다스리고 국민은 따르기만 한다","mis":"SO6-1-u2-X27"},{"t":"세 기관은 서로 관계없이 일하고 국민도 관여하지 않는다","mis":"SO6-1-u2-X29"},{"t":"국민이 세 기관의 일을 모두 직접 맡는다","mis":"SO6-1-u2-X01"}],"explanation":["세 기관이 나눠요.","서로 견제해요.","국민이 지켜봐요."]}'::jsonb),
('g6_1_soc_u2_L09_challenge#10','soc',6,1,'u2','L09','g6_1_soc_u2_L09_challenge','lesson_challenge','SO6-1-u2-C14',4,'essay','teacher','만화 속 동물 나라에서 생긴 문제를 쓰고, 우리나라가 권력을 나눠 맡게 한 방법과 그 까닭을 견주어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u2-C14","difficulty":4,"kind":"essay","stem":"만화 속 동물 나라에서 생긴 문제를 쓰고, 우리나라가 권력을 나눠 맡게 한 방법과 그 까닭을 견주어 쓰세요.","answer_guide":{"answer":"예: 동물 나라에서는 왕 혼자 법을 만들고 나라 살림을 맡고 판결까지 내려, 불편한 법을 만들어도 막을 곳이 없었고 동물들은 권리를 말하지 못했다. 우리나라는 헌법으로 국회는 법을 만들고 행정부는 나라 살림을 맡고 법원은 재판을 하도록 권력을 나누었다. 서로 견제하고 균형을 이루어 한 기관이 마음대로 하지 못하게 하여 국민의 자유와 권리를 보장하기 위해서이다.","scoring_points":["동물 나라의 문제를 썼는가","세 기관이 나눠 맡은 힘을 썼는가","견제와 균형·자유와 권리로 까닭을 썼는가"]},"explanation":["한 자리에 모였어요.","셋으로 나눠요.","자유와 권리를 지켜요."],"asset":{"type":"passage","lines":["동물들이 뽑은 왕이 법도 혼자 만들고,","나라 살림도 혼자 맡고, 다툼의 판결도 혼자 내렸다.","왕이 불편한 법을 만들어도 막을 곳이 없었고,","동물들은 자기 권리를 말하지 못했다."],"title":"교과서 만화를 내 말로 줄인 것"}}'::jsonb),
