('g6_1_soc_u2_review_a#16','soc',6,1,'u2','','g6_1_soc_u2_review_a','unit_review','SO6-1-u2-C18',2,'mc','auto','신문 ⑧의 대화방 글을 기준에 따라 살필 때 걸리는 자리로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X37']::text[],false,'{"seq":16,"concept":"SO6-1-u2-C18","difficulty":2,"kind":"mc","stem":"신문 ⑧의 대화방 글을 기준에 따라 살필 때 걸리는 자리로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"뉴스 형식을 흉내 냈고 믿을 만한 출처가 없다","correct":true},{"t":"글쓴이와 날짜가 적혀 있다","mis":"SO6-1-u2-X37"},{"t":"대화방에 올라왔다","mis":"SO6-1-u2-X37"},{"t":"걸리는 자리가 하나도 없다","mis":"SO6-1-u2-X37"}],"explanation":["속보를 붙였어요.","출처가 들은 이야기예요.","두 곳이 걸려요."],"asset":{"type":"passage","lines":["「속보 — 다음 주부터 운동장 사용 금지」라는 글이 대화방에 퍼졌다.","글쓴이와 날짜는 적혀 있었지만 출처는 「들은 이야기」뿐이었다.","학교 누리집에서 확인해 보니 사실이 아니었다.","솔빛반 기자단은 출처를 밝혀 바로잡는 기사를 썼다."],"title":"신문 ⑧ — 소문, 그대로 믿어도 될까?"}}'::jsonb),
