('g6_1_soc_u2_review_c#13','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C13',2,'ox','auto','신문 ⑤에서 법원이 재판의 과정과 결과를 공개하는 것은 공정한 재판을 위한 제도예요.',ARRAY['SO6-1-u2-X25']::text[],false,'{"seq":13,"concept":"SO6-1-u2-C13","difficulty":2,"kind":"ox","stem":"신문 ⑤에서 법원이 재판의 과정과 결과를 공개하는 것은 공정한 재판을 위한 제도예요.","answer":"O","reason_options":[{"t":"국민이 재판을 지켜보며 믿을 수 있게 하기 때문에","correct":true},{"t":"재판은 감출수록 공정하기 때문에","mis":"SO6-1-u2-X25"}],"mis":"SO6-1-u2-X25","explanation":["공개해요.","지켜볼 수 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["행정 각부가 만든 카드 뉴스로 교육·환경 소식을 알게 되었다.","대통령이 자리를 비운 사이 국무총리가 그 일을 대신 맡는다는 것도 배웠다.","법원 누리집에서 재판의 과정과 결과를 공개한다는 안내를 보았다."],"title":"신문 ⑤ — 나랏일을 나눠 맡는 곳들"}}'::jsonb),
('g6_1_soc_u2_review_c#14','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C14',2,'ox','auto','신문 ⑥의 넷째 컷처럼 세 곳이 서로 살피는 까닭은 서로를 미워하기 때문이에요.',ARRAY['SO6-1-u2-X29']::text[],false,'{"seq":14,"concept":"SO6-1-u2-C14","difficulty":2,"kind":"ox","stem":"신문 ⑥의 넷째 컷처럼 세 곳이 서로 살피는 까닭은 서로를 미워하기 때문이에요.","answer":"X","reason_options":[{"t":"서로 바로잡아 권력이 올바르게 쓰이게 하려는 것이기 때문에","correct":true},{"t":"세 곳은 서로 도우면 안 되기 때문에","mis":"SO6-1-u2-X29"}],"mis":"SO6-1-u2-X29","explanation":["바로잡으려는 거예요.","미워해서가 아니에요.","그래서 X예요."],"asset":{"type":"passage","lines":["첫째 컷 — 한 사람이 법도 만들고 살림도 맡고 판결도 내린다.","둘째 컷 — 아무도 그 사람을 막지 못한다.","셋째 컷 — 힘을 세 곳이 나눠 맡는다.","넷째 컷 — 세 곳이 서로 살피며 균형을 이룬다."],"title":"신문 ⑥ — 네 컷 만화 「힘이 한곳에 모이면」"}}'::jsonb),
('g6_1_soc_u2_review_c#15','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C16',2,'ox','auto','신문 ⑦에서 소식지를 읽은 주민들이 모여 의견을 나눈 것은 미디어가 사람들의 생각을 모으는 모습이에요.',ARRAY['SO6-1-u2-X33']::text[],false,'{"seq":15,"concept":"SO6-1-u2-C16","difficulty":2,"kind":"ox","stem":"신문 ⑦에서 소식지를 읽은 주민들이 모여 의견을 나눈 것은 미디어가 사람들의 생각을 모으는 모습이에요.","answer":"O","reason_options":[{"t":"미디어로 주고받은 정보와 생각이 의사 결정에 영향을 미치기 때문에","correct":true},{"t":"소식지는 읽는 사람의 생각과 관계없기 때문에","mis":"SO6-1-u2-X33"}],"mis":"SO6-1-u2-X33","explanation":["소식지를 읽었어요.","모여 의견을 나눴어요.","그래서 O예요."],"asset":{"type":"passage","lines":["마을 하천에 쓰레기가 쌓인 문제를 알리고 해결 방법을 내놓았다.","이웃을 배려하는 말을 쓰자는 글도 실었다.","새로 정해진 분리배출 날짜를 신속하게 알렸다.","소식지를 읽은 주민들이 모여 의견을 나누었다."],"title":"신문 ⑦ — 솔빛 마을 소식지가 한 일"}}'::jsonb),
('g6_1_soc_u2_review_c#16','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C19',2,'ox','auto','신문 ⑧에서 기자단이 출처를 밝혀 바로잡는 기사를 쓴 것은 읽는 사람에게 신뢰를 주는 방법이에요.',ARRAY['SO6-1-u2-X40']::text[],false,'{"seq":16,"concept":"SO6-1-u2-C19","difficulty":2,"kind":"ox","stem":"신문 ⑧에서 기자단이 출처를 밝혀 바로잡는 기사를 쓴 것은 읽는 사람에게 신뢰를 주는 방법이에요.","answer":"O","reason_options":[{"t":"어디에서 확인한 내용인지 알면 사실인지 판단할 수 있기 때문에","correct":true},{"t":"출처는 기사를 길게 만들기만 하기 때문에","mis":"SO6-1-u2-X40"}],"mis":"SO6-1-u2-X40","explanation":["출처를 밝혔어요.","확인할 수 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["「속보 — 다음 주부터 운동장 사용 금지」라는 글이 대화방에 퍼졌다.","글쓴이와 날짜는 적혀 있었지만 출처는 「들은 이야기」뿐이었다.","학교 누리집에서 확인해 보니 사실이 아니었다.","솔빛반 기자단은 출처를 밝혀 바로잡는 기사를 썼다."],"title":"신문 ⑧ — 소문, 그대로 믿어도 될까?"}}'::jsonb),
