('g6_1_soc_u2_review_d#19','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C12',3,'mc','auto','세 국가기관이 하는 일을 견주어 바르게 설명한 것은 어느 것인가요?',ARRAY['SO6-1-u2-X18','SO6-1-u2-X17']::text[],false,'{"seq":19,"concept":"SO6-1-u2-C12","difficulty":3,"kind":"mc","stem":"세 국가기관이 하는 일을 견주어 바르게 설명한 것은 어느 것인가요?","options":[{"t":"국회는 법을 만들고, 행정부는 법에 따라 살림을 맡고, 법원은 법에 따라 판결한다","correct":true},{"t":"국회는 판결하고, 법원은 법을 만든다","mis":"SO6-1-u2-X18"},{"t":"행정부가 법을 만들고 판결도 한다","mis":"SO6-1-u2-X18"},{"t":"세 기관은 법과 관계없이 일한다","mis":"SO6-1-u2-X17"}],"explanation":["법을 만들어요.","살림을 맡아요.","판결해요."]}'::jsonb),
('g6_1_soc_u2_review_d#20','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C14',3,'mc','auto','권력 분립과 국민의 자유·권리의 관계를 가장 바르게 말한 것은 어느 것인가요?',ARRAY['SO6-1-u2-X27','SO6-1-u2-X29']::text[],false,'{"seq":20,"concept":"SO6-1-u2-C14","difficulty":3,"kind":"mc","stem":"권력 분립과 국민의 자유·권리의 관계를 가장 바르게 말한 것은 어느 것인가요?","options":[{"t":"권력이 나뉘어 서로 견제할수록 국민의 자유와 권리가 침해받을 가능성이 줄어든다","correct":true},{"t":"권력이 한곳에 모일수록 국민의 권리가 커진다","mis":"SO6-1-u2-X27"},{"t":"권력 분립은 국민의 권리와 관계없다","mis":"SO6-1-u2-X29"},{"t":"권력을 나누면 국민의 권리가 줄어든다","mis":"SO6-1-u2-X29"}],"explanation":["나뉘면 마음대로 못 해요.","침해가 줄어요.","자유와 권리를 지켜요."]}'::jsonb),
('g6_1_soc_u2_review_d#21','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C16',3,'mc','auto','미디어가 민주주의에서 「안내소」에 빗대어지는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X33','SO6-1-u2-X32']::text[],false,'{"seq":21,"concept":"SO6-1-u2-C16","difficulty":3,"kind":"mc","stem":"미디어가 민주주의에서 「안내소」에 빗대어지는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사람들이 함께 결정하는 데 필요한 정보를 얻도록 길을 알려 주기 때문에","correct":true},{"t":"사람들이 정보를 얻지 못하게 막기 때문에","mis":"SO6-1-u2-X33"},{"t":"한 사람의 생각만 전하기 때문에","mis":"SO6-1-u2-X33"},{"t":"옛날 일만 알려 주기 때문에","mis":"SO6-1-u2-X32"}],"explanation":["안내소는 길을 알려 줘요.","필요한 정보를 줘요.","결정을 도와요."]}'::jsonb),
('g6_1_soc_u2_review_d#22','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C19',3,'mc','auto','같은 사건을 다룬 두 친구의 기사가 서로 다를 때 가장 알맞은 태도는 어느 것인가요?',ARRAY['SO6-1-u2-X39','SO6-1-u2-X36','SO6-1-u2-X38']::text[],false,'{"seq":22,"concept":"SO6-1-u2-C19","difficulty":3,"kind":"mc","stem":"같은 사건을 다룬 두 친구의 기사가 서로 다를 때 가장 알맞은 태도는 어느 것인가요?","options":[{"t":"무엇을 실었는지 견주고 사실·과장·출처를 기준에 따라 살펴본다","correct":true},{"t":"먼저 쓴 기사가 옳다고 정한다","mis":"SO6-1-u2-X39"},{"t":"둘 다 거짓이라고 정한다","mis":"SO6-1-u2-X36"},{"t":"내 생각과 같은 기사만 믿는다","mis":"SO6-1-u2-X38"}],"explanation":["실은 것이 달라요.","기준으로 살펴요.","견주어 봐요."]}'::jsonb),
('g6_1_soc_u2_review_d#23','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C1',4,'mc','auto','「민주주의와 시민 참여」 단원을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO6-1-u2-X01','SO6-1-u2-X27','SO6-1-u2-X37']::text[],false,'{"seq":23,"concept":"SO6-1-u2-C1","difficulty":4,"kind":"mc","stem":"「민주주의와 시민 참여」 단원을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"국민은 선거로 대표를 뽑고, 권력이 나뉜 국가기관을 지켜보며, 미디어를 비판적으로 이용해 민주주의에 참여한다","correct":true},{"t":"국민은 대표를 뽑은 뒤 나랏일에서 손을 뗀다","mis":"SO6-1-u2-X01"},{"t":"국가기관 하나가 모든 권력을 갖는 것이 좋다","mis":"SO6-1-u2-X27"},{"t":"미디어의 정보는 그대로 믿으면 된다","mis":"SO6-1-u2-X37"}],"explanation":["선거예요.","국가기관과 권력 분립이에요.","미디어예요."]}'::jsonb),
('g6_1_soc_u2_review_d#24','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C14',4,'essay','teacher','신문 ⑥의 네 컷을 보고 권력이 한곳에 모일 때의 문제와 권력을 나누어 얻는 점을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-1-u2-C14","difficulty":4,"kind":"essay","stem":"신문 ⑥의 네 컷을 보고 권력이 한곳에 모일 때의 문제와 권력을 나누어 얻는 점을 쓰세요.","answer_guide":{"answer":"예: 첫째·둘째 컷처럼 한 사람이 법도 만들고 살림도 맡고 판결도 내리면 아무도 막지 못해 권력을 마음대로 쓰고 잘못된 결정을 내려도 바로잡기 어렵다. 셋째·넷째 컷처럼 힘을 국회·행정부·법원이 나눠 맡으면 서로 견제하고 균형을 이루어 국민의 자유와 권리를 지킬 수 있다.","scoring_points":["권력 집중의 문제를 썼는가","세 곳이 나눠 맡음을 썼는가","견제와 균형·자유와 권리를 이어 썼는가"]},"explanation":["둘째 컷이 문제예요.","넷째 컷이 해결이에요.","얻는 점을 써요."],"asset":{"type":"passage","lines":["첫째 컷 — 한 사람이 법도 만들고 살림도 맡고 판결도 내린다.","둘째 컷 — 아무도 그 사람을 막지 못한다.","셋째 컷 — 힘을 세 곳이 나눠 맡는다.","넷째 컷 — 세 곳이 서로 살피며 균형을 이룬다."],"title":"신문 ⑥ — 네 컷 만화 「힘이 한곳에 모이면」"}}'::jsonb),
('g6_1_soc_u2_review_d#25','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C18',4,'essay','teacher','신문 ⑧처럼 확인되지 않은 소식을 받았을 때 살펴볼 기준 두 가지와 내가 할 행동을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-1-u2-C18","difficulty":4,"kind":"essay","stem":"신문 ⑧처럼 확인되지 않은 소식을 받았을 때 살펴볼 기준 두 가지와 내가 할 행동을 쓰세요.","answer_guide":{"answer":"예: 먼저 「속보」처럼 뉴스 형식을 흉내 내고 있는지 살피고, 믿을 만한 출처에서 얻은 정보인지 확인하겠다. 신문 ⑧의 글은 두 기준에 모두 걸리므로 그대로 믿거나 다른 사람에게 보내지 않고, 학교 누리집 같은 믿을 만한 다른 자료로 사실인지 확인하겠다.","scoring_points":["살펴볼 기준 두 가지를 썼는가","신문 ⑧의 글에 기준을 적용했는가","공유하지 않고 확인하는 행동을 썼는가"]},"explanation":["기준을 떠올려요.","⑧에 적용해요.","할 행동을 써요."],"asset":{"type":"passage","lines":["「속보 — 다음 주부터 운동장 사용 금지」라는 글이 대화방에 퍼졌다.","글쓴이와 날짜는 적혀 있었지만 출처는 「들은 이야기」뿐이었다.","학교 누리집에서 확인해 보니 사실이 아니었다.","솔빛반 기자단은 출처를 밝혀 바로잡는 기사를 썼다."],"title":"신문 ⑧ — 소문, 그대로 믿어도 될까?"}}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('SO6-1-u3-C1','soc',6,1,'u3',1,'지구본의 특징 — 실제 지구의 모습을 작게 줄여 만든 공 모양 모형 · 나라의 이름과 국경선 등이 입체적으로 나타남 · 세계 여러 나라의 위치·면적·지역 간 거리가 비교적 정확함 · 공 모양이라 반대쪽이 가려져 세계의 모습을 한눈에 볼 수 없고 가지고 다니기 불편함',ARRAY['[6사09-01] 지구본, 세계지도, 디지털 영상 지도 등 다양한 자료의 특징을 이해하고, 위도와 경도를 이용해 위치를 표현한다(차시 머리 주석 기준)']::text[],1),
('SO6-1-u3-C2','soc',6,1,'u3',1,'세계지도의 특징 — 둥근 지구를 평면으로 나타낸 것 · 둥근 지구의 표면을 펼치면 빈 곳이 생기고 그 빈 곳을 육지나 바다로 채워 네모반듯한 지도를 만듦 · 세계의 모습을 한눈에 살펴볼 수 있고 가지고 다니기 편리함 · 위치·면적·지역 간 거리가 실제와 다르게 나타날 수 있음(흔히 보는 세계지도에서 위쪽 땅이 실제보다 넓어 보이기도 함) · 그래서 세계지도를 여러 모양으로 만들기도 함',ARRAY['[6사09-01] 지구본, 세계지도, 디지털 영상 지도 등 다양한 자료의 특징을 이해하고, 위도와 경도를 이용해 위치를 표현한다(차시 머리 주석 기준)']::text[],2),
('SO6-1-u3-C3','soc',6,1,'u3',1,'쓰임에 따라 자료 고르기 — 지구본과 세계지도는 좋고 나쁨이 아니라 쓰임이 다름 · 같은 두 자리를 이어도 세계지도(자를 대어 곧게)와 지구본(실을 매어 팽팽히)에서 지나는 길이 다름 · 한눈에 보기·들고 다니기·여행 경로 한눈에 나타내기는 세계지도, 실제 모습·위치와 면적을 비교적 정확하게는 지구본 · 무엇을 하려는지에 따라 알맞은 자료를 고름',ARRAY['[6사09-01] 지구본, 세계지도, 디지털 영상 지도 등 다양한 자료의 특징을 이해하고, 위도와 경도를 이용해 위치를 표현한다(차시 머리 주석 기준)']::text[],3),
('SO6-1-u3-C4','soc',6,1,'u3',2,'디지털 영상 지도의 뜻 — 항공 사진이나 위성 영상에 장소나 지역의 이름, 경계선 등을 표시한 지도 · 위에서 찍은 사진이나 영상 위에 이름과 경계선을 더해 만듦 · 컴퓨터나 스마트기기 화면으로 봄 · 세계를 표현하는 자료에는 지구본, 세계지도, 디지털 영상 지도 등이 있음',ARRAY['[6사09-01] 지구본, 세계지도, 디지털 영상 지도 등 다양한 자료의 특징을 이해하고, 위도와 경도를 이용해 위치를 표현한다(차시 머리 주석 기준)']::text[],4),
('SO6-1-u3-C5','soc',6,1,'u3',2,'디지털 영상 지도의 기능 — 장소 검색(검색창에 장소를 넣어 위치 확인), 확대·축소(지도를 늘리거나 줄임), 거리 보기(여러 장소의 실제 모습을 사진으로), 거리 측정(두 자리 사이의 곧은 거리), 지도 유형 설정(원하는 지도로 바꿈) · 장소를 검색하면 소개하는 글, 교통편, 다녀온 사람들의 기록도 볼 수 있음',ARRAY['[6사09-01] 지구본, 세계지도, 디지털 영상 지도 등 다양한 자료의 특징을 이해하고, 위도와 경도를 이용해 위치를 표현한다(차시 머리 주석 기준)']::text[],5),
('SO6-1-u3-C6','soc',6,1,'u3',2,'디지털 영상 지도의 특징과 이용 — 확대와 축소가 자유로워 특정 지역을 자세히 보거나 세계를 전체적으로 볼 수 있음 · 사진이나 영상으로 실제 모습 그대로 볼 수 있음 · 장소 간 거리나 이동 시간 등 다양한 정보를 얻음 · 같은 자리도 확대·축소에 따라 한 번에 보이는 만큼이 달라짐(넓게 보면 어느 쪽인지, 가까이 보면 실제 모습) · 축소해 지구 모양이 나오게 하면 전체를 볼 수 있음 · 화면은 지금 보이는 것만 보여 주므로 살펴본 것은 적어 두어야 남음 · 언제나 가장 좋은 자료는 아니고 쓰임이 다름',ARRAY['[6사09-01] 지구본, 세계지도, 디지털 영상 지도 등 다양한 자료의 특징을 이해하고, 위도와 경도를 이용해 위치를 표현한다(차시 머리 주석 기준)']::text[],6),
('SO6-1-u3-C7','soc',6,1,'u3',3,'위선·위도·적도 — 지구본과 세계지도에는 위치를 쉽게 찾도록 가상의 가로선과 세로선을 그어 놓음 · 가로선인 위선은 위도를 나타냄 · 위도는 적도를 기준으로 남북으로 얼마나 떨어져 있는지 나타내며 북쪽과 남쪽으로 각각 90°씩 나뉨 · 적도는 위도 0°로 위도의 기준선 · 적도 북쪽은 북위, 남쪽은 남위',ARRAY['[6사09-01] 지구본, 세계지도, 디지털 영상 지도 등 다양한 자료의 특징을 이해하고, 위도와 경도를 이용해 위치를 표현한다(차시 머리 주석 기준)']::text[],7),
('SO6-1-u3-C8','soc',6,1,'u3',3,'위도에 따른 햇볕과 계절 — 지구는 둥글어서 위도에 따라 햇볕을 받는 양이 다름 · 저위도는 햇볕이 수직에 가깝게 들어와 좁은 지역에 열이 모여 기온이 높고, 고위도는 햇볕이 비스듬히 들어와 넓은 지역으로 열이 퍼져 기온이 낮음 · 지구가 기울어진 채 태양 주위를 돌아 계절의 변화가 나타나고 두 반구의 계절이 서로 반대 · 남북으로 옮기면 위도가 달라져 햇볕을 받는 양이 달라지고, 동서로 옮기면 그대로',ARRAY['[6사09-01] 지구본, 세계지도, 디지털 영상 지도 등 다양한 자료의 특징을 이해하고, 위도와 경도를 이용해 위치를 표현한다(차시 머리 주석 기준)']::text[],8),
('SO6-1-u3-C9','soc',6,1,'u3',3,'경선·경도·본초 자오선 — 세로선인 경선은 경도를 나타냄 · 경도는 본초 자오선을 기준으로 동서로 얼마나 떨어져 있는지 나타내며 동쪽과 서쪽으로 각각 180°씩 나뉨 · 본초 자오선은 경도 0° 선 · 같은 경도인 지점을 이은 경선은 북극과 남극을 지나는 세로선이고, 지구본에서 모든 경선은 북극과 남극으로 모임 · 본초 자오선 동쪽은 동경, 서쪽은 서경',ARRAY['[6사09-01] 지구본, 세계지도, 디지털 영상 지도 등 다양한 자료의 특징을 이해하고, 위도와 경도를 이용해 위치를 표현한다(차시 머리 주석 기준)']::text[],9),
('SO6-1-u3-C10','soc',6,1,'u3',3,'경도와 시차 — 시차는 세계 각 지역의 시간 차이 · 지구가 하루에 한 바퀴씩 스스로 돌기 때문에 경도에 따라 시각이 달라짐 · 어느 지역이 아침일 때 다른 지역은 저녁일 수 있음 · 시차로 생기는 교류의 불편을 줄이려고 기준이 되는 경선을 정해 그 시각을 씀 · 국토가 가로로 긴 나라는 여러 시각을 쓰기도, 하나의 통일된 시각을 쓰기도 함 · 동서로 옮기면 경도가 달라져 시각이 달라지고 남북으로 옮기면 그대로',ARRAY['[6사09-01] 지구본, 세계지도, 디지털 영상 지도 등 다양한 자료의 특징을 이해하고, 위도와 경도를 이용해 위치를 표현한다(차시 머리 주석 기준)']::text[],10),
('SO6-1-u3-C11','soc',6,1,'u3',4,'위선과 경선으로 위치 표현하기 — 지구본이나 세계지도에서는 위선과 경선이 만나는 지점으로 위치를 표현함 · 위선 하나 위에도, 경선 하나 위에도 여러 자리가 있어 한 선만으로는 자리가 하나로 정해지지 않음 · 두 선이 만나야 하나로 정해지고, 어느 선을 먼저 그어도 만나는 지점은 같음 · 그래서 위도와 경도를 함께 써서 나타냄',ARRAY['[6사09-01] 지구본, 세계지도, 디지털 영상 지도 등 다양한 자료의 특징을 이해하고, 위도와 경도를 이용해 위치를 표현한다(차시 머리 주석 기준)']::text[],11),
('SO6-1-u3-C12','soc',6,1,'u3',4,'기준선이 지나는 나라와 범위로 나타내기 — 적도가 지나는 나라: 케냐·인도네시아·에콰도르 등 · 본초 자오선이 지나는 나라: 영국·프랑스·알제리 등 · 한 지점이 아니라 위도와 경도의 범위로도 나타냄(북위 30°~40°, 서경 90°~100° → 미국 · 남위 10°~20°, 서경 40°~50° → 브라질 · 남위 20°~30°, 동경 120°~130° → 오스트레일리아) · 북위인지 남위인지, 동경인지 서경인지 먼저 가리고 위도와 경도의 범위를 함께 봐야 자리를 좁힐 수 있음',ARRAY['[6사09-01] 지구본, 세계지도, 디지털 영상 지도 등 다양한 자료의 특징을 이해하고, 위도와 경도를 이용해 위치를 표현한다(차시 머리 주석 기준)']::text[],12),
('SO6-1-u3-C13','soc',6,1,'u3',4,'공간 정보와 공간 정보 연구원 — 공간 정보는 공간상에 있는 물체의 위치나 특성에 관한 정보이고 지도도 대표적인 공간 정보 · 공간 정보 연구원은 물체의 크기와 높이 등을 바탕으로 공간 정보를 만들고, 도로·교통·도시 계획 등 여러 분야에서 목적에 맞게 활용하며, 국토를 효율적으로 관리하도록 국가 차원에서 활용하기도 함 · 토지·교통·도시 계획에 관심, 컴퓨터를 다루는 능력, 시각적 이미지를 정확하게 파악하는 능력이 도움이 됨',ARRAY['[6사09-01] 지구본, 세계지도, 디지털 영상 지도 등 다양한 자료의 특징을 이해하고, 위도와 경도를 이용해 위치를 표현한다(차시 머리 주석 기준)']::text[],13),
('SO6-1-u3-C14','soc',6,1,'u3',5,'대륙과 대양의 뜻과 이름 — 지구의 표면은 육지와 바다로 이루어지고 바다가 더 넓음 · 대륙은 바다로 둘러싸인 커다란 육지, 대양은 세계의 바다 가운데 넓은 바다 · 대륙 일곱: 아시아, 오세아니아, 유럽, 아프리카, 북아메리카, 남아메리카, 남극 대륙 · 대양 다섯: 태평양, 대서양, 인도양, 북극해, 남극해 · 대륙은 주로 대양을 기준으로 나누고 높은 산맥 등을 경계로 나누기도 함',ARRAY['[6사09-02] 세계의 대륙과 대양의 위치를 알고, 여러 대륙에 속한 나라의 위치와 영토의 특징을 탐구한다(차시 머리 주석 기준)']::text[],14),
('SO6-1-u3-C15','soc',6,1,'u3',5,'대륙과 대양의 위치와 특징 — 가장 넓은 대륙은 아시아, 가장 넓은 대양은 태평양이며 모든 대륙을 합쳐도 태평양보다 작음 · 북반구에 주로: 아시아·유럽·아프리카·북아메리카, 남반구에 주로: 오세아니아·남아메리카·남극 대륙 · 넓은 차례: 태평양 → 대서양 → 인도양 · 태평양은 아시아·오세아니아·북아메리카·남아메리카 사이, 인도양은 아시아·아프리카·오세아니아에 접함, 북극해는 아시아·유럽·북아메리카에 둘러싸인 북극 주변 바다, 남극해는 남극 대륙을 둘러싼 바다 · 남극 대륙은 얼음으로 덮여 매우 추워 사람이 살기 어려움 · 대륙과 대양은 서로 맞닿아 있음',ARRAY['[6사09-02] 세계의 대륙과 대양의 위치를 알고, 여러 대륙에 속한 나라의 위치와 영토의 특징을 탐구한다(차시 머리 주석 기준)']::text[],15),
('SO6-1-u3-C16','soc',6,1,'u3',6,'아시아와 아시아의 여러 나라 — 아시아는 세계에서 가장 넓은 대륙으로 대부분 북반구에 있음 · 동쪽에는 태평양, 서쪽에는 유럽 대륙과 아프리카 대륙 · 바다로 둘러싸인 나라도, 바다에 접하지 않은 나라도 있음 · 일본: 우리나라의 동쪽, 태평양에 접한 섬나라, 네 개의 큰 섬과 수천 개의 작은 섬 · 중국: 우리나라의 서쪽, 영토가 동서로 넓게 펼쳐짐, 동쪽에서 서쪽으로 갈수록 지형이 높아짐 · 사우디아라비아: 아시아의 서쪽, 아시아와 아프리카를 잇는 아라비아반도의 대부분, 국경선이 비교적 단조로움',ARRAY['[6사09-02] 세계의 대륙과 대양의 위치를 알고, 여러 대륙에 속한 나라의 위치와 영토의 특징을 탐구한다(차시 머리 주석 기준)']::text[],16),
('SO6-1-u3-C17','soc',6,1,'u3',6,'우리나라의 위치와 영토 — 북위 33°~43°, 동경 124°~132° 사이 · 북반구, 아시아 대륙의 동쪽 · 동쪽에 일본, 서쪽에 중국, 북쪽으로 중국·러시아와 국경을 맞댐 · 남북으로 긴 모양, 한반도와 여러 섬으로 이루어짐, 동·서·남 삼면이 바다로 둘러싸임 · 영토 면적이 비슷한 나라는 영국 · 지구본에 투명 종이를 올려 본떠 다른 나라와 겹쳐 면적을 견줄 수 있음',ARRAY['[6사09-02] 세계의 대륙과 대양의 위치를 알고, 여러 대륙에 속한 나라의 위치와 영토의 특징을 탐구한다(차시 머리 주석 기준)']::text[],17),
('SO6-1-u3-C18','soc',6,1,'u3',6,'오세아니아와 오세아니아의 여러 나라 — 세계에서 가장 작은 대륙으로 대부분 남반구에 있음 · 오스트레일리아 대륙과 태평양의 수많은 섬으로 이루어짐 · 동쪽에 태평양, 서쪽에 인도양 · 오스트레일리아: 오세아니아에서 가장 큰 나라, 태평양과 인도양 사이, 땅이 매우 넓어 나라 자체가 하나의 대륙 · 뉴질랜드: 북동쪽에서 남서쪽으로 길게 뻗음, 두 개의 큰 섬과 여러 작은 섬 · 니우에: 태평양의 섬나라, 수영과 다이빙을 즐기는 관광 산업이 발달할 수 있음 — 영토의 특징이 산업에 영향을 줌',ARRAY['[6사09-02] 세계의 대륙과 대양의 위치를 알고, 여러 대륙에 속한 나라의 위치와 영토의 특징을 탐구한다(차시 머리 주석 기준)']::text[],18),
('SO6-1-u3-C19','soc',6,1,'u3',6,'외교관 — 우리나라를 대표해 세계 여러 나라와 협력하고 외교 문제를 해결함 · 대부분 외국에 파견되어 의견을 주고받으며 두 나라의 정치·경제·문화 등을 발전시키고, 국내에서는 외교와 관련한 정책을 세우기도 함 · 여러 나라의 정치·경제·역사·문화에 관한 지식, 외국어를 익히는 흥미, 원활하게 소통하는 능력이 도움이 됨',ARRAY['[6사09-02] 세계의 대륙과 대양의 위치를 알고, 여러 대륙에 속한 나라의 위치와 영토의 특징을 탐구한다(차시 머리 주석 기준)']::text[],19),
('SO6-1-u3-C20','soc',6,1,'u3',7,'유럽과 유럽의 여러 나라 — 우랄산맥을 경계로 아시아의 서쪽, 북쪽으로 북극해·서쪽으로 대서양과 접함 · 작은 대륙이지만 많은 나라가 있음 · 노르웨이: 북동쪽에서 남서쪽으로 길게 뻗고 해안선이 복잡, 스발바르 제도에 우리나라의 다산 과학 기지 · 영국: 유럽 서쪽의 섬나라, 본초 자오선이 지나며 우리나라와 면적이 비슷 · 독일: 아홉 나라와 국경을 맞대고 북쪽은 바다와 맞닿음, 북쪽에서 남쪽으로 갈수록 지형이 높아지고 큰 강이 남북으로 흐름 · 아이슬란드는 바다로 둘러싸임, 스위스는 바다에 접하지 않음, 프랑스는 본초 자오선이 지남, 핀란드는 러시아와 국경을 마주함 · 러시아는 우랄산맥 서쪽은 유럽, 동쪽은 아시아 · 제도는 모든 섬 또는 여러 섬',ARRAY['[6사09-02] 세계의 대륙과 대양의 위치를 알고, 여러 대륙에 속한 나라의 위치와 영토의 특징을 탐구한다(차시 머리 주석 기준)']::text[],20),
('SO6-1-u3-C21','soc',6,1,'u3',7,'아프리카와 아프리카의 여러 나라 — 유럽의 남쪽, 아시아 다음으로 넓은 대륙, 가장 많은 나라 · 적도를 기준으로 북반구와 남반구에 걸쳐 있어 두 반구의 나라가 모두 있음(적도를 선으로 그어 북쪽과 남쪽으로 구분: 알제리·수단·리비아·이집트·나이지리아 / 나미비아·앙골라·마다가스카르) · 남아프리카 공화국: 남쪽 끝, 동쪽으로 인도양·서쪽으로 대서양 · 에티오피아: 동부, 여러 나라에 둘러싸여 접한 바다가 없음 · 이집트: 북동쪽 끝, 아시아와 육지로 이어지고 유럽과 가까우며 국경선 일부가 직선이라 사각형과 비슷 · 아프리카 여러 나라의 반듯한 국경선은 과거 유럽 여러 나라가 식민지로 삼으며 원래 국경을 무시하고 위도나 경도에 따라 직선을 그었기 때문',ARRAY['[6사09-02] 세계의 대륙과 대양의 위치를 알고, 여러 대륙에 속한 나라의 위치와 영토의 특징을 탐구한다(차시 머리 주석 기준)']::text[],21),
('SO6-1-u3-C22','soc',6,1,'u3',7,'나라 안의 나라 — 한 나라 안에 자리 잡은 나라가 있음 · 산마리노: 유럽 남부, 이탈리아의 영토에 둘러싸임 · 바티칸 시국: 이탈리아의 수도에 둘러싸인 세계에서 가장 작은 나라, 도시 국가(하나의 도시로 이루어진 국가) · 레소토: 아프리카 남부, 남아프리카 공화국에 둘러싸이고 영토가 직사각형과 비슷',ARRAY['[6사09-02] 세계의 대륙과 대양의 위치를 알고, 여러 대륙에 속한 나라의 위치와 영토의 특징을 탐구한다(차시 머리 주석 기준)']::text[],22),
('SO6-1-u3-C23','soc',6,1,'u3',8,'북아메리카와 북아메리카의 여러 나라 — 세 번째로 큰 대륙, 세계에서 가장 큰 섬인 그린란드를 포함, 동쪽으로 대서양·서쪽으로 태평양과 접함, 모든 나라가 바다와 접함 · 캐나다: 미국과 함께 대부분을 차지, 태평양·대서양·북극해에 접하고 남쪽으로 미국 본토와 국경(일부 직선) · 미국: 캐나다를 사이에 두고 본토와 알래스카 지역으로 나뉘며 오세아니아에 속하는 하와이 제도도 영토 · 멕시코: 북아메리카 남부, 북서쪽에서 남동쪽으로 길게 뻗음 · 본토는 국가의 주가 되는 국토',ARRAY['[6사09-02] 세계의 대륙과 대양의 위치를 알고, 여러 대륙에 속한 나라의 위치와 영토의 특징을 탐구한다(차시 머리 주석 기준)']::text[],23),
('SO6-1-u3-C24','soc',6,1,'u3',8,'남아메리카와 남아메리카의 여러 나라 — 북아메리카의 남쪽, 대부분 남반구, 세계에서 가장 긴 산맥인 안데스산맥 · 브라질: 가장 넓은 나라, 절반에 가까운 면적, 열 나라와 국경, 북부에 큰 강 · 칠레: 동서 길이에 비해 남북 길이가 매우 김, 동쪽에 안데스산맥·서쪽은 태평양 · 아르헨티나: 남부, 남북으로 길고 동쪽으로 대서양 · 바다에 접하지 않은 나라는 볼리비아·파라과이 · 브라질과 국경을 마주하지 않은 나라는 에콰도르·칠레',ARRAY['[6사09-02] 세계의 대륙과 대양의 위치를 알고, 여러 대륙에 속한 나라의 위치와 영토의 특징을 탐구한다(차시 머리 주석 기준)']::text[],24),
('SO6-1-u3-C25','soc',6,1,'u3',8,'지협과 두 대륙의 이어짐 — 지협은 두 개의 육지를 연결하는 좁고 잘록한 땅 · 북아메리카와 남아메리카는 파나마 지협으로 이어짐 · 파나마는 북아메리카의 가장 남쪽 나라로 영토 전체가 두 대륙을 잇는 지협이고 동서 길이가 남북 길이보다 김 · 두 쪽에 함께 닿아야 이어지며, 크기(가장 큰 섬·가장 긴 산맥)로 이어지는 것이 아님',ARRAY['[6사09-02] 세계의 대륙과 대양의 위치를 알고, 여러 대륙에 속한 나라의 위치와 영토의 특징을 탐구한다(차시 머리 주석 기준)']::text[],25),
('SO6-1-u3-C26','soc',6,1,'u3',9,'가 보고 싶은 나라와 여행 경로 — 대륙별로 가 보고 싶은 나라를 하나씩 정하고 까닭 쓰기(남극 대륙을 뺀 여섯 대륙) → 지구본·세계지도·디지털 영상 지도로 위치와 영토의 특징 살펴보기 → 대륙 및 나라의 위치를 고려해 여행 경로를 만들어 세계지도에 나타내기 → 친구들에게 소개하고 인상 깊은 점 발표 · 여행 경로는 출발한 곳에서 시작해 출발한 곳으로 돌아와야 닫힘(돌아오는 걸음은 나라를 늘리지 않음) · 가 보고 싶은 까닭은 사람마다 다르고 어느 나라도 더 좋거나 나쁘지 않음 · 정보 활용 능력과 창의적 사고력',ARRAY['[6사09-01] 지구본, 세계지도, 디지털 영상 지도 등 다양한 자료의 특징을 이해하고, 위도와 경도를 이용해 위치를 표현한다(차시 머리 주석 기준) / [6사09-02] 세계의 대륙과 대양의 위치를 알고, 여러 대륙에 속한 나라의 위치와 영토의 특징을 탐구한다(차시 머리 주석 기준)']::text[],26)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('SO6-1-u3-X01','soc',6,'u3',ARRAY['SO6-1-u3-C3']::text[],'지구본과 세계지도 가운데 어느 한 자료가 언제나 더 좋다고 여겨 쓰임에 따라 고르는 것을 놓친다','좋고 나쁨이 아니라 쓰임이 달라요'),
('SO6-1-u3-X02','soc',6,'u3',ARRAY['SO6-1-u3-C1']::text[],'지구본의 특징을 잘못 안다(한눈에 세계를 다 볼 수 있다고, 들고 다니기 편하다고, 평면이라고 여기는 등)','공 모양 · 반대쪽은 가려져요'),
('SO6-1-u3-X03','soc',6,'u3',ARRAY['SO6-1-u3-C2']::text[],'세계지도에 나타난 위치·면적·거리가 언제나 실제와 같다고 여긴다','평면에 펼치면 달라질 수 있어요'),
('SO6-1-u3-X04','soc',6,'u3',ARRAY['SO6-1-u3-C2']::text[],'세계지도가 어떻게 만들어지는지 잘못 안다(사진을 그대로 붙인 것으로, 지구본을 잘라 붙인 것으로 여기는 등)','둥근 표면을 펼치고 빈 곳을 채워요'),
('SO6-1-u3-X05','soc',6,'u3',ARRAY['SO6-1-u3-C3']::text[],'하려는 일에 알맞은 자료를 잘못 고른다(한눈에 보려는데 지구본을, 면적을 정확히 견주려는데 세계지도를 고르는 등)','무엇을 하려는지 먼저 봐요'),
('SO6-1-u3-X06','soc',6,'u3',ARRAY['SO6-1-u3-C4']::text[],'디지털 영상 지도의 뜻을 잘못 안다(종이에 그린 지도나 공 모양 모형으로 여기는 등)','사진·영상 위에 이름과 경계선'),
('SO6-1-u3-X07','soc',6,'u3',ARRAY['SO6-1-u3-C5']::text[],'디지털 영상 지도의 기능과 그 기능으로 하는 일을 잘못 짝짓는다','검색 · 확대·축소 · 거리 보기 · 거리 측정'),
('SO6-1-u3-X08','soc',6,'u3',ARRAY['SO6-1-u3-C6']::text[],'확대·축소를 거꾸로 알거나, 화면을 늘리고 줄이면 보고 있는 자리가 바뀐다고 여긴다','줄이면 넓게 · 늘리면 자세히 · 자리는 그대로'),
('SO6-1-u3-X09','soc',6,'u3',ARRAY['SO6-1-u3-C6']::text[],'디지털 영상 지도가 언제나 가장 좋은 자료라고 여기거나, 화면을 보기만 해도 살펴본 것이 저절로 남는다고 여긴다','쓰임이 달라요 · 적어 두어야 남아요'),
('SO6-1-u3-X10','soc',6,'u3',ARRAY['SO6-1-u3-C7','SO6-1-u3-C9']::text[],'위도와 경도의 뜻을 서로 바꾸어 안다','위도는 남북 · 경도는 동서'),
('SO6-1-u3-X11','soc',6,'u3',ARRAY['SO6-1-u3-C7','SO6-1-u3-C9']::text[],'위도와 경도의 기준선(적도·본초 자오선)을 서로 바꾸거나, 위선과 경선을 바꾸어 안다','적도는 가로 · 본초 자오선은 세로'),
('SO6-1-u3-X12','soc',6,'u3',ARRAY['SO6-1-u3-C7','SO6-1-u3-C9']::text[],'위도와 경도가 나뉘는 크기를 잘못 안다(위도를 180°까지, 경도를 90°까지로 여기는 등)','위도 90° · 경도 180°'),
('SO6-1-u3-X13','soc',6,'u3',ARRAY['SO6-1-u3-C7','SO6-1-u3-C9','SO6-1-u3-C12']::text[],'북위·남위, 동경·서경의 방향을 바꾸어 읽는다','적도 북쪽이 북위 · 본초 자오선 동쪽이 동경'),
('SO6-1-u3-X14','soc',6,'u3',ARRAY['SO6-1-u3-C8']::text[],'위도에 따라 햇볕을 받는 양이 달라지는 까닭이나 저위도·고위도의 기온을 바꾸어 안다','저위도는 좁은 곳에 모여요'),
('SO6-1-u3-X15','soc',6,'u3',ARRAY['SO6-1-u3-C8']::text[],'두 반구의 계절이 반대인 까닭을 잘못 안다(태양과의 거리, 한쪽에 햇볕이 아예 안 들어서 등)','지구가 기울어진 채 돌아요'),
('SO6-1-u3-X16','soc',6,'u3',ARRAY['SO6-1-u3-C10']::text[],'시차가 생기는 까닭을 잘못 알거나, 시각이 위도에 따라 달라진다고 여긴다','스스로 돌아요 · 경도에 따라'),
('SO6-1-u3-X17','soc',6,'u3',ARRAY['SO6-1-u3-C8','SO6-1-u3-C10']::text[],'남북으로 옮기면 시각이, 동서로 옮기면 햇볕을 받는 양이 달라진다고 바꾸어 안다','남북은 위도 · 동서는 경도'),
('SO6-1-u3-X18','soc',6,'u3',ARRAY['SO6-1-u3-C11']::text[],'위선이나 경선 하나만으로 위치가 하나로 정해진다고 여긴다','두 선이 만나야 하나'),
('SO6-1-u3-X19','soc',6,'u3',ARRAY['SO6-1-u3-C11']::text[],'위선과 경선을 긋는 차례에 따라 만나는 지점이 달라진다고 여긴다','차례와 관계없이 같아요'),
('SO6-1-u3-X20','soc',6,'u3',ARRAY['SO6-1-u3-C12']::text[],'적도가 지나는 나라와 본초 자오선이 지나는 나라를 바꾸어 안다','케냐 · 영국'),
('SO6-1-u3-X21','soc',6,'u3',ARRAY['SO6-1-u3-C12']::text[],'위도와 경도의 범위로 나라를 찾을 때 한쪽만 보거나 반구를 잘못 가린다','위도와 경도를 함께'),
('SO6-1-u3-X22','soc',6,'u3',ARRAY['SO6-1-u3-C13']::text[],'공간 정보나 공간 정보 연구원이 하는 일을 잘못 안다(정보를 감추는 일, 지도는 공간 정보가 아니라고 여기는 등)','만들고 여러 분야에 활용해요'),
('SO6-1-u3-X23','soc',6,'u3',ARRAY['SO6-1-u3-C14']::text[],'대륙과 대양의 뜻을 바꾸어 알거나, 바다를 모두 대양이라고 여긴다','대륙은 육지 · 대양은 넓은 바다'),
('SO6-1-u3-X24','soc',6,'u3',ARRAY['SO6-1-u3-C14']::text[],'대륙의 이름과 대양의 이름을 섞거나 대륙·대양의 수를 잘못 안다','대륙 일곱 · 대양 다섯'),
('SO6-1-u3-X25','soc',6,'u3',ARRAY['SO6-1-u3-C15']::text[],'가장 넓은 대륙·대양을 잘못 알거나, 모든 대륙을 합치면 태평양보다 넓다고 여긴다','아시아 · 태평양'),
('SO6-1-u3-X26','soc',6,'u3',ARRAY['SO6-1-u3-C15']::text[],'대양과 그 둘레의 대륙을 잘못 짝짓는다','둘레에 어떤 대륙이 있나요'),
('SO6-1-u3-X27','soc',6,'u3',ARRAY['SO6-1-u3-C15','SO6-1-u3-C16','SO6-1-u3-C18','SO6-1-u3-C24']::text[],'대륙이 주로 속한 반구를 바꾸어 안다(오세아니아·남아메리카를 북반구로 여기는 등)','적도의 위쪽인가 아래쪽인가'),
('SO6-1-u3-X28','soc',6,'u3',ARRAY['SO6-1-u3-C16','SO6-1-u3-C18']::text[],'아시아와 오세아니아의 특징을 바꾸어 안다(가장 넓은 대륙과 가장 작은 대륙)','아시아는 가장 넓고 오세아니아는 가장 작아요'),
('SO6-1-u3-X29','soc',6,'u3',ARRAY['SO6-1-u3-C16']::text[],'일본·중국·사우디아라비아의 위치와 영토 특징을 서로 바꾸어 안다','섬나라 · 동서로 넓게 · 반도'),
('SO6-1-u3-X30','soc',6,'u3',ARRAY['SO6-1-u3-C17']::text[],'우리나라의 위치나 영토 특징을 잘못 안다(동서로 길다고, 주변 나라의 방향을 바꾸는 등)','남북으로 길고 삼면이 바다'),
('SO6-1-u3-X31','soc',6,'u3',ARRAY['SO6-1-u3-C18']::text[],'나라의 영토 특징이 그 나라의 산업에 영향을 준다는 것을 놓친다','섬나라 → 바다를 즐기는 관광'),
('SO6-1-u3-X32','soc',6,'u3',ARRAY['SO6-1-u3-C19']::text[],'외교관이 하는 일을 잘못 안다','나라를 대표해 협력하고 문제를 해결해요'),
('SO6-1-u3-X33','soc',6,'u3',ARRAY['SO6-1-u3-C20']::text[],'유럽의 위치나 특징을 잘못 안다(우랄산맥의 동쪽이라고, 나라가 적다고 여기는 등)','우랄산맥 서쪽 · 작지만 나라가 많아요'),
('SO6-1-u3-X34','soc',6,'u3',ARRAY['SO6-1-u3-C20']::text[],'유럽 여러 나라의 영토 특징을 서로 바꾸어 안다','길게 뻗음 · 섬나라 · 아홉 나라와 국경'),
('SO6-1-u3-X35','soc',6,'u3',ARRAY['SO6-1-u3-C21']::text[],'아프리카가 한 반구에만 있다고 여기거나 아프리카의 위치·크기를 잘못 안다','북반구와 남반구에 걸쳐 있어요'),
('SO6-1-u3-X36','soc',6,'u3',ARRAY['SO6-1-u3-C21']::text[],'아프리카 여러 나라의 위치와 영토 특징을 서로 바꾸어 안다','남쪽 끝 · 바다 없음 · 사각형'),
('SO6-1-u3-X37','soc',6,'u3',ARRAY['SO6-1-u3-C21']::text[],'아프리카 여러 나라의 국경선이 반듯한 까닭을 잘못 안다(땅이 평평해서, 저절로 생겨서 등)','식민지로 삼으며 직선을 그었어요'),
('SO6-1-u3-X38','soc',6,'u3',ARRAY['SO6-1-u3-C22']::text[],'나라 안의 나라를 둘러싼 나라를 잘못 짝짓거나 도시 국가의 뜻을 잘못 안다','이탈리아 · 남아프리카 공화국'),
('SO6-1-u3-X39','soc',6,'u3',ARRAY['SO6-1-u3-C23']::text[],'북아메리카의 위치나 나라의 영토 특징을 잘못 안다(미국 영토가 한 덩어리라고, 바다와 접하지 않은 나라가 있다고 여기는 등)','본토와 알래스카 · 모든 나라가 바다와 접해요'),
('SO6-1-u3-X40','soc',6,'u3',ARRAY['SO6-1-u3-C24']::text[],'남아메리카 여러 나라의 영토 특징을 서로 바꾸어 안다','가장 넓음 · 남북으로 매우 김 · 바다에 접하지 않음'),
('SO6-1-u3-X41','soc',6,'u3',ARRAY['SO6-1-u3-C25']::text[],'지협의 뜻을 잘못 알거나, 크기가 크면 두 대륙을 잇는다고 여긴다','좁고 잘록한 땅 · 두 쪽에 함께 닿아야'),
('SO6-1-u3-X42','soc',6,'u3',ARRAY['SO6-1-u3-C26']::text[],'여행 경로를 만드는 방법을 잘못 안다(위치를 고려하지 않는다고, 출발한 곳으로 돌아오지 않아도 된다고 여기는 등)','위치를 고려 · 돌아와야 닫혀요'),
('SO6-1-u3-X43','soc',6,'u3',ARRAY['SO6-1-u3-C26','SO6-1-u3-C3']::text[],'어느 나라나 자료를 언제나 더 좋거나 나쁜 것으로 여겨, 까닭과 쓰임이 사람과 상황마다 다르다는 것을 놓친다','사람마다 · 상황마다 달라요')
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g6_1_soc_u3_L01_basic#1','soc',6,1,'u3','L01','g6_1_soc_u3_L01_basic','lesson_basic','SO6-1-u3-C1',1,'mc','auto','실제 지구의 모습을 작게 줄여 만든 공 모양 모형을 무엇이라고 하나요?',ARRAY['SO6-1-u3-X04','SO6-1-u3-X02']::text[],false,'{"seq":1,"concept":"SO6-1-u3-C1","difficulty":1,"kind":"mc","stem":"실제 지구의 모습을 작게 줄여 만든 공 모양 모형을 무엇이라고 하나요?","options":[{"t":"지구본","correct":true},{"t":"세계지도","mis":"SO6-1-u3-X04"},{"t":"사진첩","mis":"SO6-1-u3-X02"},{"t":"달력","mis":"SO6-1-u3-X02"}],"explanation":["공 모양이에요.","지구를 작게 줄였어요.","지구본이에요."]}'::jsonb),
('g6_1_soc_u3_L01_basic#2','soc',6,1,'u3','L01','g6_1_soc_u3_L01_basic','lesson_basic','SO6-1-u3-C2',1,'sa','auto','둥근 지구를 평면으로 나타낸 자료를 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-1-u3-C2","difficulty":1,"kind":"sa","stem":"둥근 지구를 평면으로 나타낸 자료를 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["세계지도"],"explanation":["평면이에요.","세계◯◯예요.","세계지도예요."],"mis":"SO6-1-u3-X04"}'::jsonb),
('g6_1_soc_u3_L01_basic#3','soc',6,1,'u3','L01','g6_1_soc_u3_L01_basic','lesson_basic','SO6-1-u3-C1',1,'ox','auto','지구본으로는 세계의 모습을 한눈에 모두 볼 수 있어요.',ARRAY['SO6-1-u3-X02']::text[],false,'{"seq":3,"concept":"SO6-1-u3-C1","difficulty":1,"kind":"ox","stem":"지구본으로는 세계의 모습을 한눈에 모두 볼 수 있어요.","answer":"X","reason_options":[{"t":"공 모양이라 반대쪽이 가려져 한 번에 다 볼 수 없기 때문에","correct":true},{"t":"지구본은 평면에 펼쳐 놓은 자료이기 때문에","mis":"SO6-1-u3-X02"}],"mis":"SO6-1-u3-X02","explanation":["지구본은 공 모양이에요.","반대쪽은 가려져요.","그래서 X예요."]}'::jsonb),
('g6_1_soc_u3_L01_basic#4','soc',6,1,'u3','L01','g6_1_soc_u3_L01_basic','lesson_basic','SO6-1-u3-C2',1,'mc','auto','세계지도의 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X03','SO6-1-u3-X02','SO6-1-u3-X06']::text[],false,'{"seq":4,"concept":"SO6-1-u3-C2","difficulty":1,"kind":"mc","stem":"세계지도의 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"세계의 모습을 한눈에 볼 수 있고 가지고 다니기 편리하다","correct":true},{"t":"면적과 거리가 언제나 실제와 똑같이 나타난다","mis":"SO6-1-u3-X03"},{"t":"공 모양이라 손으로 돌려 볼 수 있다","mis":"SO6-1-u3-X02"},{"t":"하늘에서 찍은 실제 모습을 그대로 보여 준다","mis":"SO6-1-u3-X06"}],"explanation":["평면이에요.","한눈에 보여요.","접어서 들고 다녀요."]}'::jsonb),
('g6_1_soc_u3_L01_basic#5','soc',6,1,'u3','L01','g6_1_soc_u3_L01_basic','lesson_basic','SO6-1-u3-C2',2,'blank','auto','세계지도는 둥근 지구의 표면을 펼쳤을 때 생기는 (    )을 육지나 바다로 채워 네모반듯하게 만들어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u3-X04']::text[],false,'{"seq":5,"concept":"SO6-1-u3-C2","difficulty":2,"kind":"blank","stem":"세계지도는 둥근 지구의 표면을 펼쳤을 때 생기는 (    )을 육지나 바다로 채워 네모반듯하게 만들어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"빈 곳","correct":true},{"t":"산","mis":"SO6-1-u3-X04"},{"t":"구름","mis":"SO6-1-u3-X04"},{"t":"그림자","mis":"SO6-1-u3-X04"}],"explanation":["둥근 것을 펼쳐 봐요.","사이사이가 벌어져요.","빈 곳이에요."]}'::jsonb),
('g6_1_soc_u3_L01_basic#6','soc',6,1,'u3','L01','g6_1_soc_u3_L01_basic','lesson_basic','SO6-1-u3-C3',2,'match','auto','두 자료의 좋은 점과 아쉬운 점을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO6-1-u3-C3","difficulty":2,"kind":"match","stem":"두 자료의 좋은 점과 아쉬운 점을 알맞게 이으세요.","pairs":[{"l":"지구본의 좋은 점","r":"위치·면적·거리가 비교적 정확하다"},{"l":"지구본의 아쉬운 점","r":"한눈에 볼 수 없고 들고 다니기 불편하다"},{"l":"세계지도의 좋은 점","r":"한눈에 볼 수 있고 들고 다니기 편리하다"},{"l":"세계지도의 아쉬운 점","r":"위치·면적·거리가 실제와 다를 수 있다"}],"mis":"SO6-1-u3-X02","explanation":["공 모양은 실제에 가까워요.","평면은 한눈에 보여요.","둘 다 좋은 점과 아쉬운 점이 있어요."]}'::jsonb),
('g6_1_soc_u3_L01_basic#7','soc',6,1,'u3','L01','g6_1_soc_u3_L01_basic','lesson_basic','SO6-1-u3-C3',2,'mc','auto','친구들이 말한 상황 가운데 ㉡에 더 알맞은 자료는 어느 것인가요?',ARRAY['SO6-1-u3-X05']::text[],false,'{"seq":7,"concept":"SO6-1-u3-C3","difficulty":2,"kind":"mc","stem":"친구들이 말한 상황 가운데 ㉡에 더 알맞은 자료는 어느 것인가요?","options":[{"t":"지구본","correct":true},{"t":"세계지도","mis":"SO6-1-u3-X05"},{"t":"국어사전","mis":"SO6-1-u3-X05"},{"t":"일기장","mis":"SO6-1-u3-X05"}],"explanation":["실제 지구의 모습이에요.","작게 줄인 모형이 있어요.","지구본이에요."],"asset":{"type":"passage","lines":["㉠ 세계를 한눈에 살펴보고 싶어.","㉡ 실제 지구의 모습을 살펴보고 싶어.","㉢ 가지고 다니기 편리한 자료면 좋겠어.","㉣ 여행 경로를 한눈에 볼 수 있게 나타내고 싶어.","㉤ 세계 여러 나라의 위치와 면적을 비교적 정확하게 보고 싶어."],"title":"친구들이 말한 다섯 상황"}}'::jsonb),
('g6_1_soc_u3_L01_basic#8','soc',6,1,'u3','L01','g6_1_soc_u3_L01_basic','lesson_basic','SO6-1-u3-C3',2,'mc','auto','교실에서 두 자료를 견주었을 때 두 줄이 지나는 자리가 달랐던 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X05','SO6-1-u3-X01','SO6-1-u3-X04']::text[],false,'{"seq":8,"concept":"SO6-1-u3-C3","difficulty":2,"kind":"mc","stem":"교실에서 두 자료를 견주었을 때 두 줄이 지나는 자리가 달랐던 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"평면에 펼친 세계지도와 공 모양 그대로인 지구본은 나타난 모습이 다르기 때문에","correct":true},{"t":"누군가 실수로 다른 두 자리를 이었기 때문에","mis":"SO6-1-u3-X05"},{"t":"자가 실보다 언제나 정확하기 때문에","mis":"SO6-1-u3-X01"},{"t":"두 자료를 만든 때가 서로 다르기 때문에","mis":"SO6-1-u3-X04"}],"explanation":["평면과 공 모양이에요.","펼치면 모습이 달라져요.","그래서 지나는 길이 달라요."],"asset":{"type":"passage","lines":["세계지도 — 멀리 떨어진 두 자리에 자를 대어 곧게 이었다.","지구본 — 같은 두 자리에 실을 매어 팽팽히 당겼다.","두 줄이 지나는 자리를 견주어 보니 서로 달랐다."],"title":"교실에서 두 자료 견주기"}}'::jsonb),
('g6_1_soc_u3_L01_basic#9','soc',6,1,'u3','L01','g6_1_soc_u3_L01_basic','lesson_basic','SO6-1-u3-C3',2,'mc','auto','이야기 속 사람이 살던 곳을 찾으려 할 때 가장 먼저 도움이 될 자료는 어느 것인가요?',ARRAY['SO6-1-u3-X05']::text[],false,'{"seq":9,"concept":"SO6-1-u3-C3","difficulty":2,"kind":"mc","stem":"이야기 속 사람이 살던 곳을 찾으려 할 때 가장 먼저 도움이 될 자료는 어느 것인가요?","options":[{"t":"세계의 모습을 나타낸 자료","correct":true},{"t":"기차 시간표만 모아 둔 책","mis":"SO6-1-u3-X05"},{"t":"어릴 적 그린 그림 한 장","mis":"SO6-1-u3-X05"},{"t":"친구에게 받은 편지","mis":"SO6-1-u3-X05"}],"explanation":["먼 곳에 내렸어요.","어디인지 찾아야 해요.","세계를 표현하는 자료가 필요해요."],"asset":{"type":"passage","lines":["어느 해, 기차에서 잠이 든 어린아이가 집에서 먼 곳에 내렸다.","어른이 된 그는 어릴 적 살던 집을 다시 찾아 나섰다.","기억에 남은 것은 크고 하얀 물탱크가 있던 기차역,","그리고 집 근처를 흐르던 강뿐이었다."],"title":"살던 곳을 다시 찾는 이야기"}}'::jsonb),
('g6_1_soc_u3_L01_basic#10','soc',6,1,'u3','L01','g6_1_soc_u3_L01_basic','lesson_basic','SO6-1-u3-C3',3,'error','auto','두 자료를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X01','SO6-1-u3-X05','SO6-1-u3-X03']::text[],false,'{"seq":10,"concept":"SO6-1-u3-C3","difficulty":3,"kind":"error","stem":"두 자료를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「지구본이 세계지도보다 언제나 더 좋은 자료야.」","correct":true,"mis_target":"SO6-1-u3-X01"},{"t":"친구 가 — 「무엇을 하려는지에 따라 알맞은 자료를 골라.」","mis":"SO6-1-u3-X05"},{"t":"친구 다 — 「세계지도는 한눈에 보기 편리해.」","mis":"SO6-1-u3-X03"}],"explanation":["언제나 더 좋은 자료가 있을까요?","쓰임이 서로 달라요.","친구 나가 잘못 말했어요."]}'::jsonb),
('g6_1_soc_u3_L01_challenge#1','soc',6,1,'u3','L01','g6_1_soc_u3_L01_challenge','lesson_challenge','SO6-1-u3-C3',2,'sa','auto','친구들이 말한 상황 가운데 ㉢에 더 알맞은 자료의 이름을 네 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u3-C3","difficulty":2,"kind":"sa","stem":"친구들이 말한 상황 가운데 ㉢에 더 알맞은 자료의 이름을 네 글자로 쓰세요.","answer":["세계지도"],"explanation":["들고 다니기 편해야 해요.","접을 수 있어요.","세계지도예요."],"asset":{"type":"passage","lines":["㉠ 세계를 한눈에 살펴보고 싶어.","㉡ 실제 지구의 모습을 살펴보고 싶어.","㉢ 가지고 다니기 편리한 자료면 좋겠어.","㉣ 여행 경로를 한눈에 볼 수 있게 나타내고 싶어.","㉤ 세계 여러 나라의 위치와 면적을 비교적 정확하게 보고 싶어."],"title":"친구들이 말한 다섯 상황"},"mis":"SO6-1-u3-X05"}'::jsonb),
