('g6_1_soc_u3_review_d#23','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C15',4,'essay','teacher','일지 ④의 수수께끼 ㉠~㉣의 답을 쓰고, 그 가운데 둘의 위치와 특징을 이어 설명하세요.','{}'::text[],false,'{"seq":23,"concept":"SO6-1-u3-C15","difficulty":4,"kind":"essay","stem":"일지 ④의 수수께끼 ㉠~㉣의 답을 쓰고, 그 가운데 둘의 위치와 특징을 이어 설명하세요.","answer_guide":{"answer":"예: ㉠은 태평양, ㉡은 남극해, ㉢은 북극해, ㉣은 남극 대륙이다. 태평양은 가장 넓은 대양으로 아시아·오세아니아·북아메리카·남아메리카 사이에 있고, 남극해는 남극 대륙을 둘러싼 바다로 둘레의 대륙이 남극 대륙 하나뿐이다.","scoring_points":["네 답을 바르게 썼는가","고른 둘의 위치를 썼는가","고른 둘의 특징을 썼는가"]},"explanation":["가장 넓은 바다예요.","두 극의 바다예요.","얼음 대륙이에요."],"asset":{"type":"passage","lines":["㉠ 가장 넓은 대양","㉡ 남극 대륙을 둘러싼 바다","㉢ 아시아·유럽·북아메리카에 둘러싸인 바다","㉣ 얼음으로 덮여 사람이 살기 어려운 대륙"],"title":"일지 ④ — 지구본 수수께끼"}}'::jsonb),
('g6_1_soc_u3_review_d#24','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C21',4,'essay','teacher','아프리카가 다른 대륙과 다른 점을 위치와 관련지어 쓰고, 아프리카 나라를 두 무리로 나누는 방법을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-1-u3-C21","difficulty":4,"kind":"essay","stem":"아프리카가 다른 대륙과 다른 점을 위치와 관련지어 쓰고, 아프리카 나라를 두 무리로 나누는 방법을 쓰세요.","answer_guide":{"answer":"예: 아프리카는 유럽의 남쪽에 있으며 적도를 기준으로 북반구와 남반구에 걸쳐 있어, 북반구에 있는 나라도 남반구에 있는 나라도 있다. 그래서 적도를 선으로 그어 그것을 기준으로 북쪽에 있는 나라와 남쪽에 있는 나라로 나눌 수 있다.","scoring_points":["아프리카의 위치를 썼는가","두 반구에 걸쳐 있음을 썼는가","적도를 기준으로 나눈다고 썼는가"]},"explanation":["유럽의 남쪽이에요.","적도가 지나요.","적도로 나눠요."]}'::jsonb),
('g6_1_soc_u3_review_d#25','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C14',4,'essay','teacher','이 단원에서 배운 대륙 일곱과 대양 다섯을 쓰고, 대륙과 대양이 서로 맞닿아 있다는 것을 예를 들어 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-1-u3-C14","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 대륙 일곱과 대양 다섯을 쓰고, 대륙과 대양이 서로 맞닿아 있다는 것을 예를 들어 설명하세요.","answer_guide":{"answer":"예: 대륙은 아시아, 오세아니아, 유럽, 아프리카, 북아메리카, 남아메리카, 남극 대륙이고, 대양은 태평양, 대서양, 인도양, 북극해, 남극해이다. 아시아는 동쪽의 태평양, 남쪽의 인도양, 북쪽의 북극해와 맞닿아 있고, 남극 대륙은 남극해에 둘러싸여 있다.","scoring_points":["대륙 일곱을 썼는가","대양 다섯을 썼는가","맞닿은 예를 들었는가"]},"explanation":["육지 일곱이에요.","바다 다섯이에요.","아시아를 예로 들어요."]}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('K6-2-u1-C1','kor',6,2,'u1',2,'작가의 의도 알기 — 작가가 글을 쓴 까닭과 읽는 사람이 느끼기를 바란 것을 작가의 의도라 하고, 같은 작품도 근거가 있으면 서로 다르게 읽을 수 있음을 알기',ARRAY['6국05 문학(초안)']::text[],1),
('K6-2-u1-C2','kor',6,2,'u1',2,'되풀이하거나 힘준 표현에서 뜻 찾기 — 작품에서 되풀이한 말, 물음으로 끝맺는 등 힘준 표현을 찾아 그 표현이 주는 느낌과 담긴 뜻을 생각하기(시조는 세 줄이라 고르고 고른 말이 실마리)',ARRAY['6국05 문학(초안)']::text[],2),
('K6-2-u1-C3','kor',6,2,'u1',2,'작가의 삶을 실마리로 작품 다시 읽기 — 작가가 살아온 삶을 알아보아 작품을 다시 보되, 삶만으로 뜻을 하나로 정하지 않고 작품으로 돌아와 근거를 찾기',ARRAY['6국05 문학(초안)']::text[],3),
('K6-2-u1-C4','kor',6,2,'u1',4,'시어의 뜻을 짐작하며 시 읽기 — 길·담·닫힌 문·발자국처럼 여러 뜻을 품은 시어가 무엇을 나타내는지 앞뒤 연을 근거로 짐작하고, 여러 번 읽으며 스스로 느낀 것과 짐작한 의도를 근거와 한 묶음으로 말하기',ARRAY['6국05 문학(초안)']::text[],4),
('K6-2-u1-C5','kor',6,2,'u1',7,'이야기 구조 알기 — 이야기를 발단(시작)·전개(사건이 본격적으로 생김)·절정(긴장감이 높아지거나 갈등이 두드러짐)·결말(마무리)로 나누고, 경계는 까닭을 말할 수 있으면 사람마다 다를 수 있음을 알기',ARRAY['6국02 읽기(초안)']::text[],5),
('K6-2-u1-C6','kor',6,2,'u1',7,'이야기의 줄거리 간추리기 — 부분마다 중요한 사건을 골라, 덜 중요한 것은 덜어 내고, 무슨 일이 왜 일어났는지 이어지도록 짧게 적기(늘어놓기·통째 옮기기·뭉뚱그리기 피하기)',ARRAY['6국02 읽기(초안)']::text[],6),
('K6-2-u1-C7','kor',6,2,'u1',9,'인물의 마음과 시간 표현 읽기 — 앞뒤 사건을 근거로 인물의 마음을 짐작하고, 지난여름·여름내·사흘째·이튿날 같은 시간을 나타내는 표현으로 일의 차례를 가려 읽으며, 이야기 속 낱말의 뜻 알기',ARRAY['6국02 읽기(초안)']::text[],7),
('K6-2-u1-C8','kor',6,2,'u1',12,'문학 작품 소개하기 — 처음(제목·작가·고른 까닭)·가운데(간추린 줄거리·짐작한 의도와 근거)·끝(내 생각·권할 사람)으로 소개하고, 광고처럼 쓰지 않으며, 찾은 글은 간추려 내 말로 쓰고 출처를 적고, 친구에게 근거를 묻는 물음 하기',ARRAY['6국05 문학(초안)']::text[],8),
('K6-2-u1-C9','kor',6,2,'u1',12,'여러 뜻을 지닌 낱말 — 차다·눈·쓰다·타다처럼 글자가 같아도 뜻이 다른 낱말을 앞뒤 문장을 보고 알맞은 뜻으로 가려 읽기(기초 다지기)',ARRAY['6국04 문법(초안)']::text[],9)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('K6-2-u1-X01','kor',6,'u1',ARRAY['K6-2-u1-C1']::text[],'작가의 의도를 모두가 똑같이 내야 하는 정답이나 작가가 살던 때의 기록으로 여긴다','쓴 사람 쪽에서 — 「왜 썼을까, 무엇을 느끼길 바랐을까?」'),
('K6-2-u1-X02','kor',6,'u1',ARRAY['K6-2-u1-C2','K6-2-u1-C4','K6-2-u1-C6','K6-2-u1-C7']::text[],'작품에 없는 내용(내 짐작·바깥 정보)을 작품에 나온 것으로 고른다','작품에 적힌 말에 밑줄부터 — 적혀 있지 않으면 근거가 아니에요'),
('K6-2-u1-X03','kor',6,'u1',ARRAY['K6-2-u1-C2']::text[],'되풀이하거나 힘준 표현을 그냥 지나가는 말로 여기거나 글자 그대로만 받아들인다(백 번 = 정확히 백 번)','두 번 나온 말, 물음으로 끝난 말에 동그라미 — 왜 힘을 줬을까?'),
('K6-2-u1-X04','kor',6,'u1',ARRAY['K6-2-u1-C1','K6-2-u1-C3']::text[],'작가의 삶만 보고 작품의 뜻을 하나로 정해 버리고 작품에서 근거를 찾지 않는다','작가의 삶은 실마리 — 「그렇다면 시의 어느 줄이?」로 돌아가기'),
('K6-2-u1-X05','kor',6,'u1',ARRAY['K6-2-u1-C3']::text[],'작가의 삶은 작품과 상관없다고 여겨 아예 알아보지 않는다','작가를 알면 그냥 지나친 말이 다시 보여요'),
('K6-2-u1-X06','kor',6,'u1',ARRAY['K6-2-u1-C1','K6-2-u1-C4','K6-2-u1-C7','K6-2-u1-C8']::text[],'근거 없이 느낌만 말하거나, 근거가 있는 다른 읽기를 틀렸다고 한다','맞고 틀림이 아니라 근거가 있고 없음'),
('K6-2-u1-X07','kor',6,'u1',ARRAY['K6-2-u1-C1']::text[],'작품을 감상하는 대신 어느 쪽이 옳은지 내 결론을 말한다','「작가는 무엇을 전하려 했나?」만 묻기'),
('K6-2-u1-X08','kor',6,'u1',ARRAY['K6-2-u1-C4']::text[],'시어를 겉뜻으로만 읽는다(담 = 집의 생김새, 발자국 = 더러운 자국)','그 낱말이 나온 연에서 인물이 어떤 처지인지 보기'),
('K6-2-u1-X09','kor',6,'u1',ARRAY['K6-2-u1-C5']::text[],'발단·전개·절정·결말을 헷갈리거나 경계가 하나로만 정해진다고 여긴다','긴장감이 가장 높은 곳(절정)부터 찾고 앞뒤를 나누기'),
('K6-2-u1-X10','kor',6,'u1',ARRAY['K6-2-u1-C6']::text[],'사건을 늘어놓기만 해서 무슨 일이 왜 일어났는지 이어지지 않는 줄거리를 쓴다','「~해서 ~하자 ~했다」처럼 이음말로 잇기'),
('K6-2-u1-X11','kor',6,'u1',ARRAY['K6-2-u1-C6','K6-2-u1-C8']::text[],'덜 중요한 것까지 통째로 옮기거나, 반대로 중요한 사건을 빼고 한 문장으로 뭉뚱그린다','부분마다 중요한 사건 하나씩 — 네 문장'),
('K6-2-u1-X12','kor',6,'u1',ARRAY['K6-2-u1-C7']::text[],'인물의 마음을 앞뒤 사건 근거 없이 엉뚱하게 짐작한다','「바로 앞에 무슨 일이 있었지? 곁에 누가 있었지?」'),
('K6-2-u1-X13','kor',6,'u1',ARRAY['K6-2-u1-C8']::text[],'작품 소개를 광고하는 말(대박·별 다섯)이나 책값·쪽수처럼 작품과 상관없는 것으로 채운다','읽는 사람이 「어떤 작품인지」 알 수 있나?'),
('K6-2-u1-X14','kor',6,'u1',ARRAY['K6-2-u1-C8']::text[],'찾은 글을 그대로 옮겨 붙이고 어디에서 찾았는지 적지 않는다','두세 줄로 간추려 내 말로 + 출처'),
('K6-2-u1-X15','kor',6,'u1',ARRAY['K6-2-u1-C7','K6-2-u1-C9']::text[],'낱말만 보고 뜻을 정해 앞뒤 문장에 맞지 않는 뜻을 고른다','그 문장이 무엇에 대한 말인지 먼저 보기'),
('K6-2-u1-X16','kor',6,'u1',ARRAY['K6-2-u1-C7']::text[],'시간을 나타내는 표현을 놓쳐 일의 차례나 때를 뒤바꾼다','지난여름·여름내·사흘째·이튿날에 동그라미'),
('K6-2-u1-X17','kor',6,'u1',ARRAY['K6-2-u1-C2','K6-2-u1-C4']::text[],'시조·시의 짜임(시조는 세 줄, 시는 연과 행)을 모르거나 표현을 형식 맞추기로만 여긴다','시조 세 줄 · 시는 연(덩어리)과 행(줄)')
